// ---------------------------------------------------------------------------
// Phase 86f Track C.3 — userspace-simd-smoke: static objdump + QEMU runtime
// ---------------------------------------------------------------------------

/// Smoke step list for `cargo xtask userspace-simd-smoke` (runtime half).
///
/// Asserts, over serial:
/// 1. `crypto-test` (SSE+AES-NI-heavy) runs fault-free and prints the
///    "all tests PASSED" sentinel (Track B.2 — signal-frame FPU + 16-aligned
///    entry stack falsifiable proof).
/// 2. `crypto-test --bench` prints a `BENCH:aes-ctr:` line (Track C.1 —
///    the AES-NI execution path ran in-OS; throughput number is NOT asserted
///    because TCG/KVM rates vary wildly).
fn userspace_simd_smoke_steps() -> Vec<SmokeStep> {
    let mut steps = boot_and_login_steps();
    // Run the correctness suite — proves the SSE-spilling binary runs without
    // a #GP misalignment or signal-frame corruption fault (Track B.2).
    steps.push(SmokeStep::Send {
        input: "/bin/crypto-test\n",
        label: "guest/simd-smoke: run crypto-test correctness suite",
    });
    steps.push(SmokeStep::Wait {
        pattern: "crypto-test: all tests PASSED",
        timeout_secs: 180,
        label: "guest/simd-smoke: crypto-test correctness PASSED (SSE binary runs fault-free)",
    });
    // Run the benchmark — proves AES-NI executes in-OS (Track C.1).
    // TCG distorts throughput numbers so we only assert the sentinel appears,
    // not any specific MiB/s value.
    steps.push(SmokeStep::Send {
        input: "/bin/crypto-test --bench\n",
        label: "guest/simd-smoke: run crypto-test --bench (AES-NI path exercise)",
    });
    steps.push(SmokeStep::Wait {
        pattern: "BENCH:aes-ctr:",
        timeout_secs: 60,
        label: "guest/simd-smoke: BENCH:aes-ctr: sentinel appeared (AES-NI path executed)",
    });
    steps
}

/// Static objdump assertions for `cargo xtask userspace-simd-smoke`.
///
/// Asserts, without booting QEMU:
/// - `objdump -d` of `crypto-test` (userspace, `x86_64-m3os.json`) contains
///   XMM-register operands (`%xmm0`..`%xmm15`) on instruction lines (count > 0).
///   Matching is restricted to instruction lines (leading whitespace) to avoid
///   false positives from mangled symbol names containing "xmm".
/// - `objdump -d` of the kernel ELF (`x86_64-unknown-none`) contains ZERO such
///   lines — the kernel stays soft-float.
/// - `objdump -d` of `crypto-test` contains `aesenc` or `aesenclast` (AES-NI).
fn userspace_simd_objdump_gate(root: &std::path::Path) {
    let userspace_elf = root.join("target/x86_64-m3os/release/crypto-test");
    let kernel_elf = root.join("target/x86_64-unknown-none/release/kernel");

    for path in &[&userspace_elf, &kernel_elf] {
        if !path.exists() {
            eprintln!(
                "userspace-simd-smoke: objdump gate: binary not found: {}",
                path.display()
            );
            eprintln!("userspace-simd-smoke: run `cargo xtask image` first to build all binaries");
            std::process::exit(1);
        }
    }

    // ── Helper: disassemble and return the text ───────────────────────────────
    let disasm = |path: &std::path::Path| -> String {
        let out = Command::new("objdump")
            .args(["-d", path.to_str().unwrap()])
            .output()
            .unwrap_or_else(|_| {
                panic!(
                    "userspace-simd-smoke: failed to spawn objdump -d {}",
                    path.display()
                )
            });
        if !out.status.success() {
            eprintln!(
                "userspace-simd-smoke: objdump -d {} exited with status {}",
                path.display(),
                out.status
            );
            std::process::exit(1);
        }
        String::from_utf8_lossy(&out.stdout).into_owned()
    };

    // ── Count XMM operands on instruction lines ───────────────────────────────
    //
    // objdump disasm lines have the form:
    //   "  <addr>:\t<hex>\t<mnemonic> <operands>"
    // They always start with whitespace.  Symbol-name lines look like:
    //   "<addr> <sym_name>:"
    // and do NOT start with whitespace, so restricting to lines that start
    // with at least one space eliminates false positives from mangled names
    // that happen to contain "xmm".
    let count_xmm = |text: &str| -> usize {
        text.lines()
            .filter(|line| {
                // Must be an instruction line (starts with whitespace).
                let Some(first) = line.chars().next() else {
                    return false;
                };
                if !first.is_whitespace() {
                    return false;
                }
                // Must contain an XMM register operand (%xmm0..%xmm15).
                // We look for literal "%xmm" anywhere on the line; valid
                // operands are "%xmm0".."%xmm15" so this substring match is
                // precise enough.
                line.contains("%xmm")
            })
            .count()
    };

    let userspace_disasm = disasm(&userspace_elf);
    let kernel_disasm = disasm(&kernel_elf);

    let userspace_xmm = count_xmm(&userspace_disasm);
    let kernel_xmm = count_xmm(&kernel_disasm);

    println!(
        "userspace-simd-smoke [objdump/xmm-userspace]: instruction lines with %xmm operands = {userspace_xmm} (must be > 0)"
    );
    if userspace_xmm == 0 {
        eprintln!(
            "userspace-simd-smoke FAIL [objdump/xmm-userspace]: no XMM-register instructions \
             found in {}.\n\
             Expected SSE/AES codegen from the x86_64-m3os.json hardware-float target.\n\
             Reproduce: objdump -d {} | grep -c '%xmm'",
            userspace_elf.display(),
            userspace_elf.display()
        );
        std::process::exit(1);
    }

    println!(
        "userspace-simd-smoke [objdump/xmm-kernel]: instruction lines with %xmm operands in kernel = {kernel_xmm} (must be 0)"
    );
    if kernel_xmm != 0 {
        eprintln!(
            "userspace-simd-smoke FAIL [objdump/xmm-kernel]: found {kernel_xmm} XMM-register \
             instruction(s) in the kernel ELF {}.\n\
             The kernel must stay soft-float (x86_64-unknown-none, -sse).\n\
             Reproduce: objdump -d {} | grep -E '^\\s' | grep -c '%xmm'",
            kernel_elf.display(),
            kernel_elf.display()
        );
        std::process::exit(1);
    }

    // ── AES-NI positive gate ──────────────────────────────────────────────────
    // Count `aesenc` and `aesenclast` instructions in the userspace binary.
    // These are emitted by the `aes` crate's AES-NI backend when the target
    // permits XMM/AES-NI codegen.
    let aesni_count = userspace_disasm
        .lines()
        .filter(|line| {
            let Some(first) = line.chars().next() else {
                return false;
            };
            if !first.is_whitespace() {
                return false;
            }
            line.contains("aesenc") || line.contains("aesenclast")
        })
        .count();

    println!(
        "userspace-simd-smoke [objdump/aes-ni]: aesenc/aesenclast instruction lines = {aesni_count} (must be > 0)"
    );
    if aesni_count == 0 {
        eprintln!(
            "userspace-simd-smoke FAIL [objdump/aes-ni]: no aesenc/aesenclast instructions \
             found in {}.\n\
             Expected hardware AES-NI from the `aes` crate's cpufeatures backend on the \
             x86_64-m3os.json (+aes) target.\n\
             Reproduce: objdump -d {} | grep -E '(aesenc|aesenclast)'",
            userspace_elf.display(),
            userspace_elf.display()
        );
        std::process::exit(1);
    }

    println!(
        "userspace-simd-smoke [objdump]: PASS — {userspace_xmm} XMM lines in userspace, \
         0 in kernel, {aesni_count} AES-NI lines in userspace"
    );
}

/// `cargo xtask userspace-simd-smoke` — Phase 86f Track C.3.
///
/// Two-phase gate:
/// 1. **Static (objdump):** build + disassemble `crypto-test` (userspace,
///    x86_64-m3os.json) and the kernel ELF (x86_64-unknown-none); assert
///    userspace has XMM-register instructions and AES-NI (aesenc/aesenclast),
///    and the kernel has none.
/// 2. **Dynamic (QEMU serial):** boot m3OS, log in, run `crypto-test` (assert
///    "all tests PASSED" — SSE binary fault-free on the 16-aligned entry
///    stack), then run `crypto-test --bench` (assert `BENCH:aes-ctr:` sentinel
///    — AES-NI executed in-OS).
fn cmd_userspace_simd_smoke(args: &SmokeBootArgs) {
    // Phase 1: build + static objdump checks.
    let kernel_binary = build_kernel();
    let root = workspace_root();
    userspace_simd_objdump_gate(&root);

    // Phase 2: QEMU runtime checks.
    let uefi_image = create_uefi_image(&kernel_binary);
    convert_to_vhdx(&uefi_image);

    let disk_img = uefi_image.parent().unwrap().join("disk.img");
    if disk_img.exists() {
        let _ = fs::remove_file(&disk_img);
    }
    create_data_disk(
        uefi_image.parent().unwrap(),
        false,
        false,
        false,
        false,
        false,
        false, // graphical_login — serial autologin path
    );

    let ovmf = find_ovmf();
    let qemu_args = session_smoke_qemu_args(&uefi_image, &ovmf, args.display);
    let steps = userspace_simd_smoke_steps();

    println!(
        "userspace-simd-smoke: launching QEMU (timeout {}s)",
        args.timeout_secs
    );

    let mut child = Command::new("qemu-system-x86_64")
        .args(&qemu_args)
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::null())
        .spawn()
        .expect("userspace-simd-smoke: failed to launch QEMU");

    let global_timeout = std::time::Duration::from_secs(args.timeout_secs);
    let start = std::time::Instant::now();

    match run_smoke_script(&mut child, &steps, global_timeout) {
        Ok(()) => {
            let elapsed = start.elapsed().as_secs();
            println!(
                "userspace-simd-smoke: PASS ({} steps in {elapsed}s)",
                steps.len()
            );
            let _ = child.kill();
            let _ = child.wait();
        }
        Err(msg) => {
            let _ = child.kill();
            let _ = child.wait();
            eprintln!("userspace-simd-smoke: FAILED\n{msg}");
            std::process::exit(1);
        }
    }
}

// ---------------------------------------------------------------------------
// Phase 63 Track E.1 — bell-smoke step list, QEMU arg builder, and command
// ---------------------------------------------------------------------------

/// Phase 63 Track E.1 (resend) — smoke step list for `cargo xtask bell-smoke`.
///
/// ## Routing fix
///
/// The original implementation injected `printf '\x07'\n` via QEMU serial
/// stdin. Serial stdin goes to the kernel serial shell (`sh0`), **not** to
/// `term`'s ANSI parser (which reads from `kbd_server`). The BEL byte never
/// reached `Bell::ring` — the old approach was broken by design.
///
/// The fix: run the `bell-test` binary from `sh0`. `bell-test` directly
/// constructs an `AudioClientBellSink` and calls `Bell::ring()`, exercising
/// the exact same code path `term`'s ANSI parser takes. No kbd_server
/// routing required.
///
/// ## Scope
///
/// Verifies that the `Bell::ring` → `AudioClientBellSink::play` →
/// `audio_client::submit_frames` → `Ac97Backend` path actually advances
/// `frames_consumed` once the real AC'97 backend (Phase 63 A/B) is live.
///
/// ## Steps
///
/// 1. Wait for the kernel boot marker.
/// 2. Wait for `init: loaded service 'audio_server'` — proves init has
///    registered the audio_server manifest entry and will spawn it. Mirrors
///    `audio_smoke_steps`'s gating: we do NOT gate on
///    `session_manager: session.boot: state=running` because that line
///    races with other markers across cores and is unrelated to whether
///    bell-test can reach the audio path from sh0.
/// 3. `boot_and_login_steps()` — wait for the post-boot `m3OS login:`
///    prompt and log into `sh0` as root. Without this, the next `Send`
///    would type `bell-test` at the login prompt instead of running it.
/// 4. Sleep 500 ms so the post-login shell finishes painting its prompt.
/// 5. `Send` `bell-test\n` to run the bell path exerciser from `sh0`.
///    `bell-test` calls `Bell::ring()` → `AudioClientBellSink::play` →
///    `audio_client::submit_frames`, sleeps 200 ms, then queries stats and
///    prints `BELL_TEST:consumed=<N> underruns=<M>` followed by
///    `BELL_TEST:PASS` or `BELL_TEST:FAIL:consumed=0` /
///    `BELL_TEST:FAIL:audio_unavailable`.
/// 6. `WaitPassOrFail` for `BELL_TEST:PASS` vs `BELL_TEST:FAIL` within
///    15 s. On `BELL_TEST:FAIL` the harness exits immediately with
///    `SMOKE_EXIT_BELL_SMOKE_FAILED` and surfaces the failing variant.
///
/// ## Why no TERM_SMOKE gating
///
/// Earlier versions of this list gated on `TERM_SMOKE:ready` and
/// `TERM_SMOKE:prompt-ready`. Those markers describe the *graphical*
/// terminal emulator and are off-path: `bell-test` runs from sh0
/// (serial), not from term's ANSI parser. The TERM_SMOKE markers also
/// race with `session_manager: state=running` on the wire (different
/// cores, ms apart) and the consuming-Wait matcher used to deadlock when
/// the wire order disagreed with the step order — see the bell-smoke
/// handoff §1 fix. The harness is now non-consuming for `Wait`, but
/// gating bell-smoke on irrelevant markers is still the wrong shape.
///
/// ## Failure modes
///
/// - If `Bell::ring` → `submit_frames` does not reach the Ac97Backend,
///   `frames_consumed` stays zero → `bell-test` prints `BELL_TEST:FAIL:consumed=0`
///   and the smoke exits.
/// - If `Ac97Backend` is absent (Phase 57 accounting stub), `frames_submitted`
///   advances but `frames_consumed` does not. Same failure path.
/// - If `audio_server` is absent, `AudioClientBellSink::ensure_open` fails
///   and `bell-test` prints `BELL_TEST:FAIL:audio_unavailable`.
fn bell_smoke_steps() -> Vec<SmokeStep> {
    let mut steps = vec![
        SmokeStep::Wait {
            pattern: "[m3os] Hello from kernel",
            timeout_secs: 30,
            label: "guest/bell-smoke: kernel first message",
        },
        SmokeStep::Wait {
            pattern: "init: loaded service 'audio_server'",
            timeout_secs: 90,
            label: "guest/bell-smoke: init loaded audio_server.conf",
        },
    ];
    // Log into sh0 so the next Send lands at a shell prompt rather than
    // `m3OS login:`. Mirrors `audio_smoke_steps`'s use of the same prefix.
    steps.extend(boot_and_login_steps());
    steps.push(SmokeStep::Sleep { millis: 500 });
    // Run the bell path exerciser from sh0. bell-test directly constructs
    // AudioClientBellSink, calls Bell::ring(), sleeps 200 ms for DMA, then
    // queries stats and prints BELL_TEST:PASS or BELL_TEST:FAIL.
    // This bypasses the kbd_server routing gap: serial stdin goes to sh0,
    // not to term's ANSI parser; bell-test invokes the bell library directly.
    steps.push(SmokeStep::Send {
        input: "bell-test\n",
        label: "guest/bell-smoke: run bell-test binary",
    });
    // WaitPassOrFail surfaces the failing variant from
    // `BELL_TEST:FAIL:consumed=0` / `BELL_TEST:FAIL:audio_unavailable`
    // immediately rather than letting the step time out generically.
    // 15 s covers: bell-test's own 200 ms tone sleep + DMA latency + sh0
    // prompt round-trip, plus headroom for slower CI.
    steps.push(SmokeStep::WaitPassOrFail {
        pass_pattern: "BELL_TEST:PASS",
        fail_prefix: "BELL_TEST:FAIL",
        timeout_secs: 15,
        label: "guest/bell-smoke: frames_consumed > 0 after Bell::ring",
        exit_code_on_fail: SMOKE_EXIT_BELL_SMOKE_FAILED,
    });
    steps
}

/// Build the QEMU arg vector for the bell-smoke.
///
/// Uses the same WAV audio backend as [`audio_smoke_qemu_args`] so
/// the smoke is deterministic (no host PulseAudio required) and the
/// recorded WAV can optionally be inspected for non-silence. The WAV
/// file is written to `<smoke_dir>/bell-smoke.wav` to avoid colliding
/// with the `audio-smoke` run's `audio.wav` when both smokes are run
/// in the same CI job.
///
/// The session-smoke QEMU flags are included (full session startup:
/// display_server + kbd + mouse + audio_server + term) because
/// bell-smoke requires `term` to be running.
fn bell_smoke_qemu_args(
    smoke_dir: &Path,
    uefi_image: &Path,
    ovmf: &Path,
    display: bool,
) -> Vec<String> {
    let display_mode = if display {
        QemuDisplayMode::Gui
    } else {
        QemuDisplayMode::Headless
    };
    let mut qemu_args =
        qemu_args_with_devices(uefi_image, ovmf, display_mode, DeviceSet::default());
    for arg in qemu_args.iter_mut() {
        if arg.starts_with("user,id=net0,hostfwd=") {
            *arg = "user,id=net0".to_string();
        }
    }
    // WAV backend for deterministic CI — same pattern as audio_smoke_qemu_args.
    let wav_path = smoke_dir.join("bell-smoke.wav");
    qemu_args.extend([
        "-audiodev".to_string(),
        format!("wav,id=snd0,path={}", wav_path.display()),
        "-device".to_string(),
        "AC97,audiodev=snd0,addr=0x5".to_string(),
    ]);
    qemu_args
}

fn cmd_bell_smoke(args: &SmokeBootArgs) {
    let kernel_binary = build_kernel();
    let uefi_image = create_uefi_image(&kernel_binary);
    convert_to_vhdx(&uefi_image);

    let disk_img = uefi_image.parent().unwrap().join("disk.img");
    if disk_img.exists() {
        let _ = fs::remove_file(&disk_img);
    }
    create_data_disk(
        uefi_image.parent().unwrap(),
        false,
        false,
        false,
        false,
        false,
        false, // graphical_login — autologin / serial path
    );

    // Prepare output directory for the WAV recording.
    let smoke_dir = prepare_audio_smoke_dir();

    let ovmf = find_ovmf();
    let qemu_args = bell_smoke_qemu_args(&smoke_dir, &uefi_image, &ovmf, args.display);
    let steps = bell_smoke_steps();

    println!(
        "bell-smoke: launching QEMU with AC'97 WAV backend (timeout {}s)",
        args.timeout_secs
    );
    println!(
        "bell-smoke: WAV output → {}",
        smoke_dir.join("bell-smoke.wav").display()
    );

    let mut child = Command::new("qemu-system-x86_64")
        .args(&qemu_args)
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::null())
        .spawn()
        .expect("failed to launch QEMU");

    let global_timeout = std::time::Duration::from_secs(args.timeout_secs);
    let start = std::time::Instant::now();

    match run_smoke_script(&mut child, &steps, global_timeout) {
        Ok(()) => {
            let elapsed = start.elapsed().as_secs();
            println!("bell-smoke: PASSED ({} steps in {elapsed}s)", steps.len());
            let _ = child.kill();
            let _ = child.wait();
        }
        Err(msg) => {
            let _ = child.kill();
            let _ = child.wait();
            eprintln!("bell-smoke: FAILED\n{msg}");
            std::process::exit(SMOKE_EXIT_BELL_SMOKE_FAILED);
        }
    }
}

/// Phase 69 Track H — boots m3OS, logs into sh0, and drives each
/// `tui-smoke <subcmd>` against the post-login shell. Asserts every
/// subcommand prints `TUI_SMOKE:<name>:ok`; the failing variant from
/// any `TUI_SMOKE:<name>:fail` is surfaced immediately with exit code
/// [`SMOKE_EXIT_TUI_SMOKE_FAILED`].
fn cmd_tui_smoke(args: &SmokeBootArgs) {
    let kernel_binary = build_kernel();
    let uefi_image = create_uefi_image(&kernel_binary);
    convert_to_vhdx(&uefi_image);

    let disk_img = uefi_image.parent().unwrap().join("disk.img");
    if disk_img.exists() {
        let _ = fs::remove_file(&disk_img);
    }
    create_data_disk(
        uefi_image.parent().unwrap(),
        false,
        false,
        false,
        false,
        false,
        false, // graphical_login — autologin / serial path
    );

    let ovmf = find_ovmf();
    let display_mode = if args.display {
        QemuDisplayMode::Gui
    } else {
        QemuDisplayMode::Headless
    };
    let mut qemu_args =
        qemu_args_with_devices(&uefi_image, &ovmf, display_mode, DeviceSet::default());
    for arg in qemu_args.iter_mut() {
        if arg.starts_with("user,id=net0,hostfwd=") {
            *arg = "user,id=net0".to_string();
        }
    }
    let steps = tui_smoke_steps();

    println!(
        "tui-smoke: launching QEMU (timeout {}s, {} subcommands)",
        args.timeout_secs,
        TUI_SMOKE_SUBCOMMANDS.len()
    );

    let mut child = Command::new("qemu-system-x86_64")
        .args(&qemu_args)
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::null())
        .spawn()
        .expect("failed to launch QEMU");

    let global_timeout = std::time::Duration::from_secs(args.timeout_secs);
    let start = std::time::Instant::now();

    match run_smoke_script(&mut child, &steps, global_timeout) {
        Ok(()) => {
            let elapsed = start.elapsed().as_secs();
            println!("tui-smoke: PASSED ({} steps in {elapsed}s)", steps.len());
            let _ = child.kill();
            let _ = child.wait();
        }
        Err(msg) => {
            let _ = child.kill();
            let _ = child.wait();
            eprintln!("tui-smoke: FAILED\n{msg}");
            std::process::exit(SMOKE_EXIT_TUI_SMOKE_FAILED);
        }
    }
}

